presets.customCss:
/* 长夜＆机械之心➠线上心声美化，建议修改key 给版式取值＜40 使用更佳*/
.xs-voice-wrap {
  background: linear-gradient(180deg, rgba(255,248,252,.75) 0%, rgba(255,224,236,.75) 100%);
  backdrop-filter: blur(28px);
  -webkit-backdrop-filter: blur(28px);
  border-radius: 24px;
  padding: 24px 16px 32px;
  position: relative;
  overflow: hidden;
  font-family: system-ui, sans-serif;
}
.xs-title {
  font-family:"Cinzel",serif;
  font-style:italic;
  font-size:22px;
  color:#d65a8c;
  margin:0 0 8px;
  position:relative; z-index:2;
}
.xs-ecg-top, .xs-ecg-bottom {
  position:absolute; left:0; right:0; height:18px; opacity:.8; pointer-events:none;
}
.xs-ecg-top { top:60px; }
.xs-ecg-bottom { bottom:0; }
.xs-ecg-top svg, .xs-ecg-bottom svg { width:100%; height:100%; }
.xs-center-line {
  position:absolute; left:50%; top:88px; bottom:36px;
  width:2px; transform:translateX(-50%);
  background:#ffb2d1; z-index:1;
}
.xs-list {
  position:relative; z-index:2;
  display:flex; flex-direction:column; gap:4px;
  margin-top:24px;
}
.xs-row {
  display:flex; align-items:center; position:relative;
}
.xs-bubble {
  width:46%; padding:9px 14px;
  background: rgba(255,255,255,.65);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-radius:20px;
  border:1px solid rgba(255,185,214,.4);
  box-shadow: 0 2px 12px rgba(236,124,160,.1);
  font-size:11.5px; line-height:1.6; color:#333;
  position:relative;
  white-space:normal; word-break:break-word;
}
.xs-bubble .content:empty::after {
  content:"机械之心";
  font-style:italic;
  color:#d65a8c;
  opacity:.5;
}
.xs-bubble.left { margin-right:auto; }
.xs-bubble.right { margin-left:auto; }
.xs-bubble .tag {
  display:block; font-size:10px; letter-spacing:1px;
  color:#d65a8c; opacity:.8; margin-bottom:2px;
}
/* 好感栏心电图+心 */
.xs-bubble .xs-favor-ecg {
  display:flex; align-items:center; gap:6px; margin-top:6px;
}
.xs-bubble .xs-favor-ecg svg.line { flex:1; height:14px; }
.xs-bubble .xs-favor-ecg svg.heart { width:12px; height:12px; flex-shrink:0; }
/* 藏掉系统原生丑进度条 */
.xs-bubble [class*="bar"] { display:none !important; }
.xs-node {
  position:absolute; left:50%; top:50%;
  transform:translate(-50%,-50%);
  width:16px; height:16px; border-radius:50%;
  background:#fff; border:3px solid #ec7ca0;
  box-shadow:0 0 0 4px rgba(236,124,160,.15);
  z-index:3;
}
